<template>
  <DialogCard :config="config.dialogData">
    <FormattedText
      v-for="(msg, index) in config.otpTexts"
      :key="index"
      :class="msg.class"
      :type="msg.type"
      :color="msg.color"
      :value="msg.text"
    />
    <v-otp-input
      v-model="otpValue"
      :length="config.codeLength"
      type="number"
      plain
      @finish="onFinish"
    />
    <div v-if="config.resendOption">
      <a
        :class="[
          { disabled: isResendDisabled },
          { 'primary--text': !isResendDisabled },
          'text-subtitle-2',
        ]"
        @click.prevent="resendOnClick()"
        ref="resendButton"
      >
        {{ getTranslatedText('shared.otpDialog.resendCode') }}
      </a>
      <span v-if="isResendDisabled"> ({{ remainingTime }}s)</span>
    </div>
  </DialogCard>
</template>

<script>
import { getTranslatedText } from '@/tools/data'
import { hashData } from '@/tools/security'

import notificationsService from '@/services/renderer/notifications'

import DialogCard from '@/components/shared/DialogCard'
import FormattedText from '@/components/shared/FormattedText'

export default {
  name: 'OneTimePasswordDialog',
  components: { DialogCard, FormattedText },
  props: {
    config: {
      type: Object,
      required: true,
    },
  },
  data() {
    return {
      otpValue: '',
      remainingAttempts: 3,
      isResendDisabled: true,
      remainingTime: 60,
    }
  },
  methods: {
    getTranslatedText,
    onFinish(otpValue) {
      const valueToCheck = this.config.isEncrypted
        ? hashData(otpValue)
        : otpValue
      this.remainingAttempts--
      if (this.config.code == valueToCheck) {
        this.sendPubSubEvent(true)
        this.config.dialogData.onClickAccept(otpValue)
      } else if (this.remainingAttempts === 0) {
        this.sendPubSubEvent(false)
        notificationsService.showError(
          'preferences.rememberPasswordDialog.noAttemptsRemaining',
          this.$vuetify.lang
        )
        this.config.dialogData.onClickCancel()
      } else {
        this.sendPubSubEvent(false)
        notificationsService.showError(
          'preferences.rememberPasswordDialog.incorrectCode',
          this.$vuetify.lang
        )
        this.otpValue = ''
        document.getElementsByClassName('otp-field-box--0')[0].focus()
      }
    },
    resendOnClick() {
      if (!this.isResendDisabled) this.config.resendOnClick()
    },
    sendPubSubEvent(isCodeCorrect) {
      if (!this.config.categoryEvent) return
      this.$track({
        type: 'interaction',
        action: 'input',
        category: this.config.categoryEvent,
        screen: this.config.screenEvent,
        name: isCodeCorrect
          ? 'Correct verification code'
          : 'Incorrect verification code',
      })
    },
  },
  mounted() {
    document.getElementsByClassName('otp-field-box--0')[0].focus()
    const interval = setInterval(() => {
      this.remainingTime--
      if (this.remainingTime <= 0) {
        this.isResendDisabled = false
        clearInterval(interval)
      }
    }, 1000)
  },
}
</script>

<style scoped>
a {
  text-decoration: none;
  cursor: pointer;
}
a.disabled {
  color: gray;
  pointer-events: none;
  cursor: not-allowed;
}
span {
  font-size: 14px;
  margin-left: 8px;
}
</style>
