const setConfig = (state, methods) => ({
  state,
  methods,
  dialogData: {
    opened: state.isOpen,
    icon: 'mdi-account-key',
    title: 'starterLayout.otpRegisterDialog.title',
    titleBackground: '#white',
    titleColor: 'textPrimary',
    persistent: true,
    buttons: {
      accept: false,
      cancel: false,
    },
    height: 245,
    maxWidth: 450,
    onClickCancel: () => methods.closeDialog(),
    onClickAccept: () => methods.createAdminPassword(),
  },
  codeLength: 4,
  code: state.code,
  isEncrypted: true,
  resendOption: true,
  resendOnClick: () => methods.resendOnClick(),
  categoryEvent: 'Signup',
  screenEvent: 'PhoneSignupOtp',
  otpTexts: [
    {
      text: methods.getTranslatedText(
        'starterLayout.otpRegisterDialog.text1',
        state.account
      ),
      class: 'pb-4',
      type: 'text-body-2',
      color: 'textPrimary',
    },
  ],
})

export default setConfig
