<template>
  <DialogCard :config="componentConfig.dialogData" class="pb-0">
    <Form v-if="!fetching" :config="componentConfig" />
    <div class="text-center" v-else>
      <transition-group appear name="fade">
        <v-progress-circular
          class="mt-4"
          size="55"
          indeterminate
          color="primary"
          key="progress"
        />
        <FormattedText
          type="text-body-2"
          :value="checkingMessage"
          intl
          class="pt-4"
          key="text"
        />
      </transition-group>
    </div>
  </DialogCard>
</template>

<script>
import { mapState, mapActions } from 'vuex'

import SIGNUP_EVENTS from '@/config/events/signUp'
import RESTORE_EVENTS from '@/config/events/restore'
import LOGIN_EVENTS from '@/config/events/login'
import PUBSUB_EVENTS from '@/config/events/pubsub'

import { cleanObjectObserver } from '@/tools/data'

import notificationsService from '@/services/renderer/notifications'
import rendererEventsService from '@/services/renderer/rendererEvents'

import appActions from '@/store/app/actions.types'
import accountActions from '@/store/account/actions.types'

import setConfig from '@/components/AuthViews/ExternalLoginView/AddAdminPasswordDialog/config'
import DialogCard from '@/components/shared/DialogCard'
import Form from '@/components/shared/Form'
import FormattedText from '@/components/shared/FormattedText'

export default {
  name: 'AddAdminPasswordDialog',
  components: { DialogCard, Form, FormattedText },
  data() {
    return {
      inputs: {},
      validators: { inputs: {} },
    }
  },
  computed: {
    ...mapState('app', ['addAdminPasswordDialog', 'countrySelected']),
    ...mapState('account', ['fetching']),
    componentConfig() {
      return setConfig(
        {
          inputs: this.inputs,
          v: this.$v.inputs,
          isOpen: this.addAdminPasswordDialog.isOpen,
          newAccount: this.addAdminPasswordDialog.newAccount,
          fetching: this.fetching,
        },
        {
          closeDialog: this.closeDialog,
          checkPasswordAndContinue: this.checkPasswordAndContinue,
        }
      )
    },
    checkingMessage() {
      return this.addAdminPasswordDialog.newAccount
        ? 'starterLayout.addAdminPasswordDialog.creatingAccount'
        : 'starterLayout.addAdminPasswordDialog.checkingAccount'
    },
  },
  validations() {
    return this.validators
  },
  methods: {
    ...mapActions('app', [appActions.setAddAdminPasswordDialogStatus]),
    ...mapActions('account', [
      accountActions.resetErrorStatus,
      accountActions.setPosDataAfterLogin,
      accountActions.setAccountFetchingStatus,
    ]),
    setProperties: function() {
      this.componentConfig.fields.forEach(field => {
        if (field.show) {
          this.$set(this.inputs, field.id, '')
          if (field.validators)
            this.$set(
              this.validators.inputs,
              field.id,
              Array.isArray(field.validators)
                ? field.validators
                : { ...cleanObjectObserver(field.validators) }
            )
        }
      })
    },
    checkPasswordAndContinue: async function() {
      if (this.$v.inputs.$invalid) {
        Object.keys(this.inputs).forEach(key => this.$v.inputs[key].$touch())
        return
      }
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Signup',
        screen: 'AddAdminPassword',
        name: 'Submit',
      })
      this[accountActions.setAccountFetchingStatus](true)
      const credentials = {
        account: this.addAdminPasswordDialog.userInfo.email,
        password: this.inputs.password,
        userName: this.addAdminPasswordDialog.userInfo.name,
        country: this.countrySelected,
      }
      if (this.addAdminPasswordDialog.newAccount) {
        rendererEventsService.send(SIGNUP_EVENTS.channel, {
          event: SIGNUP_EVENTS.events.signUpProcess.name,
          data: { credentials, online: navigator.onLine },
        })
      } else {
        rendererEventsService.send(LOGIN_EVENTS.channel, {
          event: LOGIN_EVENTS.events.accountLoginProcess.name,
          data: { credentials: credentials, online: navigator.onLine },
        })
      }
    },
    loginListener(event, payload) {
      const replies = {
        [LOGIN_EVENTS.events.accountLoginProcess.replies.start]: () => {
          this[accountActions.setAccountFetchingStatus](true)
        },
        [LOGIN_EVENTS.events.accountLoginProcess.replies.error]: () => {
          this[accountActions.setAccountFetchingStatus](false)
          if (payload.error.error === 'Connection error')
            notificationsService.showError(
              payload.error.message,
              this.$vuetify.lang,
              { timeout: 10000 }
            )
          else if (payload.error.message === 'Invalid pass') {
            this.inputs.password = ''
            notificationsService.showError(
              payload.error.error,
              this.$vuetify.lang,
              { timeout: 10000 }
            )
          } else {
            notificationsService.showError(
              'starterLayout.login.unknownError',
              this.$vuetify.lang,
              { timeout: 10000 }
            )
          }
        },
        [LOGIN_EVENTS.events.accountLoginProcess.replies.success]: () => {
          rendererEventsService.send(PUBSUB_EVENTS.channel, {
            event: PUBSUB_EVENTS.events.updatePosInfo.name,
            data: { pos: payload.data.pos },
          })
          this.$track({
            type: 'system',
            action: 'api_call',
            category: 'Signup',
            screen: 'Login',
            name: 'Start restore process',
          })
          this.loginProcess = true
          this[accountActions.setPosDataAfterLogin]({
            posData: payload.data,
            pendingSyncOps: 1,
          })
          rendererEventsService.send(RESTORE_EVENTS.channel, {
            event: RESTORE_EVENTS.events.restoreProcess.name,
            data: { posData: payload.data },
          })
          this.closeDialog()
          this.$router.push({ name: 'Restore' })
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
    signupListener(event, payload) {
      const replies = {
        [SIGNUP_EVENTS.events.signUpProcess.replies.start]: () => {
          this[accountActions.setAccountFetchingStatus](true)
        },
        [SIGNUP_EVENTS.events.signUpProcess.replies.error]: () => {
          this[accountActions.setAccountFetchingStatus](false)
          if (payload.error.error === 'Connection error')
            notificationsService.showError(
              payload.error.message,
              this.$vuetify.lang,
              { timeout: 10000 }
            )
          else {
            notificationsService.showError(
              'starterLayout.login.unknownError',
              this.$vuetify.lang,
              { timeout: 10000 }
            )
            this.closeDialog()
          }
        },
        [SIGNUP_EVENTS.events.signUpProcess.replies.success]: () => {
          rendererEventsService.send(PUBSUB_EVENTS.channel, {
            event: PUBSUB_EVENTS.events.updatePosInfo.name,
            data: { pos: payload.data.pos },
          })
          this.$track({
            type: 'system',
            action: 'api_call',
            category: 'Signup',
            screen: 'AddAdminPassword',
            name: 'Start download process',
          })
          this.loginProcess = true
          this[accountActions.setPosDataAfterLogin]({
            posData: payload.data,
            pendingSyncOps: 1,
          })
          rendererEventsService.send(RESTORE_EVENTS.channel, {
            event: RESTORE_EVENTS.events.restoreProcess.name,
            data: { posData: payload.data },
          })
          this.closeDialog()
          this.$router.push({ name: 'SignUpProfile' })
        },
      }
      if (payload.event in replies) replies[payload.event]()
    },
    closeDialog() {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Signup',
        screen: 'AddAdminPassword',
        name: 'Cancel',
      })
      this[appActions.setAddAdminPasswordDialogStatus]({ isOpen: false })
      this.$emit('adminPwDialogClosed')
    },
  },
  mounted() {
    this.setProperties()
    rendererEventsService.subscribe(
      SIGNUP_EVENTS.replyChannel,
      this.signupListener
    )
    rendererEventsService.subscribe(
      LOGIN_EVENTS.replyChannel,
      this.loginListener
    )
  },
  beforeDestroy() {
    rendererEventsService.removeListener(
      SIGNUP_EVENTS.replyChannel,
      this.signupListener
    )
    rendererEventsService.removeListener(
      LOGIN_EVENTS.replyChannel,
      this.loginListener
    )
  },
}
</script>

<style scoped>
.fade-enter {
  opacity: 0;
}
.fade-enter-active {
  transition: opacity 2s ease-out;
}
</style>
