import {
  maxLength,
  minLength,
  required,
  sameAs,
} from 'vuelidate/lib/validators'

const setConfig = (state, methods) => ({
  state,
  methods,
  dialogData: {
    opened: state.isOpen,
    icon: 'mdi-lock-outline',
    title: 'starterLayout.addAdminPasswordDialog.title',
    titleBackground: '#white',
    titleColor: 'textPrimary',
    buttons: {
      accept: !state.fetching,
      cancel: !state.fetching,
    },
    buttonTextColor: {
      cancel: 'white',
      accept: 'white',
    },
    buttonColor: {
      cancel: 'accent',
      accept: 'primary',
    },
    messages: state.newAccount
      ? ['starterLayout.addAdminPasswordDialog.toSignUp']
      : ['starterLayout.addAdminPasswordDialog.toRestore'],
    height: state.newAccount ? 380 : 300,
    maxWidth: 500,
    id: 'confirm-admin-password-form',
    onClickCancel: () => methods.closeDialog(),
    onClickAccept: () => methods.checkPasswordAndContinue(),
  },
  fields: [
    {
      id: 'password',
      type: 'password',
      validators: {
        required,
        maxLength: maxLength(30),
        minLength: minLength(4),
      },
      autofocus: true,
      show: true,
    },
    {
      id: 'repeatPassword',
      type: 'password',
      validators: { required, sameAsPassword: sameAs('password') },
      label: 'preferences.changePasswordDialog.repeatPassword',
      show: state.newAccount ? true : false,
    },
  ],
  id: 'confirm-admin-password-form',
})

export default setConfig
