<template>
  <div>
    <v-card class="px-6 pt-6 pb-2 form-card">
      <div class="primary form-top-bar" />
      <div class="d-flex position-relative">
        <v-btn
          icon
          @click="goBack"
          v-track:click="{
            category: 'Signup',
            screen: 'PhoneSignup',
            name: 'Change country',
          }"
          class="text-decoration-none"
        >
          <v-icon color="primary">mdi-arrow-left</v-icon>
        </v-btn>
        <FormattedText type="text-caption" class="centered-element">
          <span>
            {{ getTranslatedText('starterLayout.common.youSelected') }}
            {{ country.name }}
          </span>
          <router-link
            to="/welcome"
            v-track:click="{
              category: 'Signup',
              screen: 'PhoneSignup',
              name: 'Change country',
            }"
          >
            <span>{{ getTranslatedText('starterLayout.common.change') }}</span>
          </router-link>
        </FormattedText>
      </div>

      <v-card-title class="flex-column justify-center pt-1">
        <FormattedText
          type="text-h6"
          intl
          value="starterLayout.externalLogin.title"
        />
      </v-card-title>
      <v-card-text class="text--primary">
        <div class="d-flex flex-column">
          <FormattedText
            type="text-body-1"
            intl
            value="starterLayout.externalLogin.subtitle"
          />
          <FormattedText
            type="text-body-2"
            intl
            value="starterLayout.externalLogin.text"
            class="mb-4"
          />
          <Form :config="formConfig" />
          <CustomButton
            block
            large
            rounded
            :disabled="$v.$invalid || loginInProcess"
            @click="submit()"
            :form="formConfig.id"
            text="starterLayout.externalLogin.submit"
            textType="text-subtitle-2"
            textClass="text-none"
            intl
            class="mt-2 mb-2"
            ref="externalLoginSubmit"
          />
          <TermsAlert />
          <FormattedText
            type="text-body-2"
            intl
            value="starterLayout.externalLogin.othersSignUp"
          />
          <div class="d-flex justify-center align-center mt-4">
            <v-tooltip bottom>
              <template v-slot:activator="{ on }">
                <v-btn
                  ref="googleLoginButton"
                  fab
                  v-on="on"
                  color="red lighten-1"
                  @click="openExternalLogin('google')"
                  class="mr-4"
                  v-track:click="{
                    category: 'Signup',
                    screen: 'PhoneSignup',
                    name: 'Google login',
                  }"
                >
                  <v-icon color="white">
                    mdi-google
                  </v-icon>
                </v-btn>
              </template>
              <span>
                {{
                  getTranslatedText('starterLayout.externalLogin.googleLogin')
                }}
              </span>
            </v-tooltip>
            <v-tooltip bottom>
              <template v-slot:activator="{ on }">
                <v-btn
                  ref="goToSignUpButton"
                  fab
                  v-on="on"
                  color="grey lighten-1"
                  @click="goToSignUp()"
                  v-track:click="{
                    category: 'Signup',
                    screen: 'PhoneSignup',
                    name: 'Go to email signup',
                  }"
                >
                  <v-icon color="white">
                    mdi-email-outline
                  </v-icon>
                </v-btn>
              </template>
              <span>
                {{
                  getTranslatedText('starterLayout.externalLogin.normalLogin')
                }}
              </span>
            </v-tooltip>
          </div>
          <v-divider class="mt-5" />
          <FormattedText class="mt-5" type="text-body-1">
            <span>
              {{ getTranslatedText('starterLayout.externalLogin.alreadyUser') }}
            </span>
            <router-link
              to="/login"
              v-track:click="{
                category: 'Signup',
                screen: 'PhoneSignup',
                name: 'Go to login',
              }"
            >
              <span ref="goToLoginButton" class="primary--text">
                {{ getTranslatedText('starterLayout.externalLogin.login') }}
              </span>
            </router-link>
          </FormattedText>
        </div>
      </v-card-text>
    </v-card>
    <AddAdminPasswordDialog
      v-if="addAdminPasswordDialog.isOpen"
      @adminPwDialogClosed="loginInProcess = false"
    />
    <OTPDialog v-if="otpRegisterDialog.isOpen" :config="otpDialogConfig" />
  </div>
</template>

<script>
import { mapActions, mapState } from 'vuex'

import countries from '@/config/countries'
import APP_TOOLS_EVENTS from '@/config/events/appTools'
import LOGIN_EVENTS from '@/config/events/login'
import SIGNUP_EVENTS from '@/config/events/signUp'

import { getTranslatedText, cleanObjectObserver } from '@/tools/data'

import rendererEventsService from '@/services/renderer/rendererEvents'
import notificationsService from '@/services/renderer/notifications'

import appActions from '@/store/app/actions.types'
import accountActions from '@/store/account/actions.types'

import FormattedText from '@/components/shared/FormattedText'
import CustomButton from '@/components/shared/CustomButton'
import Form from '@/components/shared/Form'
import OTPDialog from '@/components/shared/OTPDialog'
import AddAdminPasswordDialog from '@/components/AuthViews/ExternalLoginView/AddAdminPasswordDialog'
import setConfig from '@/components/AuthViews/ExternalLoginView/ExternalLoginViewForm/config'
import setOtpDialogConfig from '@/components/AuthViews/ExternalLoginView/otpDialogConfig'
import TermsAlert from '@/components/AuthViews/TermsAlert'

export default {
  name: 'ExternalLoginViewForm',
  components: {
    TermsAlert,
    FormattedText,
    CustomButton,
    AddAdminPasswordDialog,
    Form,
    OTPDialog,
  },
  data() {
    return {
      inputs: {},
      validators: { inputs: {} },
      loginInProcess: false,
      userInfo: null,
    }
  },
  computed: {
    ...mapState('app', [
      'countrySelected',
      'addAdminPasswordDialog',
      'otpRegisterDialog',
    ]),
    country() {
      return countries[this.countrySelected]
    },
    formConfig() {
      return setConfig(
        { inputs: this.inputs, v: this.$v.inputs },
        { submit: this.submit }
      )
    },
    otpDialogConfig() {
      return setOtpDialogConfig(
        {
          isOpen: this.otpRegisterDialog.isOpen,
          code: this.otpRegisterDialog.code,
          account: this.inputs.account,
        },
        {
          closeDialog: this.closeOptDialog,
          createAdminPassword: this.createAdminPassword,
          getTranslatedText: this.getTranslatedText,
          resendOnClick: this.resendOnClick,
        }
      )
    },
  },
  methods: {
    ...mapActions('app', [
      appActions.setAddAdminPasswordDialogStatus,
      appActions.setTermsDialogStatus,
      appActions.setOtpRegisterDialogStatus,
    ]),
    ...mapActions('account', [
      accountActions.setAccountFetchingStatus,
      accountActions.resetErrorStatus,
      accountActions.setPosDataAfterLogin,
    ]),
    getTranslatedText,
    goBack() {
      this.$router.go(-1)
    },
    openExternalLogin(authProvider) {
      if (!this.loginInProcess) {
        rendererEventsService.send(APP_TOOLS_EVENTS.channel, {
          event: APP_TOOLS_EVENTS.events.externalLogin.name,
          data: { authProvider },
        })
      }
    },
    goToSignUp() {
      if (!this.loginInProcess) this.$router.push({ path: '/sign-up' })
    },
    setProperties() {
      this.formConfig.fields.forEach(field => {
        this.$set(this.inputs, field.id, '')
        if (field.validators) {
          this.$set(
            this.validators.inputs,
            field.id,
            Array.isArray(field.validators)
              ? field.validators
              : { ...cleanObjectObserver(field.validators) }
          )
        }
      })
    },
    submit() {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Signup',
        screen: 'PhoneSignup',
        name: 'Submit',
      })
      this.loginInProcess = true
      const credentials = {
        account: this.inputs.account,
        country: this.country.phoneCode,
      }
      rendererEventsService.send(SIGNUP_EVENTS.channel, {
        event: SIGNUP_EVENTS.events.validatePhone.name,
        data: { credentials: credentials, online: navigator.onLine },
      })
    },
    closeOptDialog() {
      this.loginInProcess = false
      this[appActions.setOtpRegisterDialogStatus]({ isOpen: false })
    },
    createAdminPassword() {
      this.closeOptDialog()
      this[appActions.setAddAdminPasswordDialogStatus]({
        isOpen: true,
        userInfo: { email: this.inputs.account, userName: '' },
        newAccount: true,
      })
    },
    resendOnClick() {
      this.$track({
        type: 'interaction',
        action: 'click',
        category: 'Signup',
        screen: 'PhoneSignup',
        name: 'Resend verification code',
      })
      this.closeOptDialog()
      setTimeout(() => this.submit(), 1000)
    },
  },
  validations() {
    return this.validators
  },
  watch: {
    $data: {
      handler: function() {
        this[accountActions.resetErrorStatus]()
      },
      deep: true,
    },
  },
  mounted() {
    this.setProperties()
    rendererEventsService.subscribe(
      APP_TOOLS_EVENTS.replyChannel,
      (event, payload) => {
        const replies = {
          [APP_TOOLS_EVENTS.events.externalLogin.replies.success]: () => {
            this.loginInProcess = true
            this.userInfo = payload.data
            this[accountActions.setAccountFetchingStatus](true)
            const credentials = {
              account: payload.data.email,
              userName: payload.data.name,
              country: this.countrySelected,
            }
            rendererEventsService.send(LOGIN_EVENTS.channel, {
              event: LOGIN_EVENTS.events.accountLoginProcess.name,
              data: { credentials: credentials, online: navigator.onLine },
            })
          },
          [APP_TOOLS_EVENTS.events.externalLogin.replies.error]: () => {
            if (payload.error !== 'closed window') {
              notificationsService.showError(
                'starterLayout.login.unknownError',
                this.$vuetify.lang,
                { timeout: 10000 }
              )
            }
          },
        }
        if (payload.event in replies) replies[payload.event]()
      }
    )
    rendererEventsService.subscribe(
      LOGIN_EVENTS.replyChannel,
      (event, payload) => {
        const replies = {
          [LOGIN_EVENTS.events.accountLoginProcess.replies.error]: () => {
            this[accountActions.setAccountFetchingStatus](false)
            if (payload.error.error === 'Connection error') {
              this.loginInProcess = false
              notificationsService.showError(
                payload.error.message,
                this.$vuetify.lang,
                { timeout: 10000 }
              )
            } else if (
              payload.error.error === 'starterLayout.login.credentialsError'
            ) {
              this[appActions.setAddAdminPasswordDialogStatus]({
                isOpen: true,
                userInfo: this.userInfo,
                newAccount: payload.error.message !== 'Invalid pass',
              })
            } else {
              this.loginInProcess = false
              notificationsService.showError(
                'starterLayout.login.unknownError',
                this.$vuetify.lang,
                { timeout: 10000 }
              )
            }
          },
        }
        if (payload.event in replies) replies[payload.event]()
      }
    )
    rendererEventsService.subscribe(
      SIGNUP_EVENTS.replyChannel,
      (event, payload) => {
        const replies = {
          [SIGNUP_EVENTS.events.validatePhone.replies.success]: () => {
            this[appActions.setOtpRegisterDialogStatus]({
              isOpen: true,
              code: payload.data.codeEncripted,
            })
          },
          [SIGNUP_EVENTS.events.validatePhone.replies.error]: () => {
            notificationsService.showError(
              payload.error.message,
              this.$vuetify.lang,
              { timeout: 10000 }
            )
            this.loginInProcess = false
            if (payload.error.error == 'account-already-exists')
              this.$router.push({
                path: '/login',
                query: { account: this.inputs.account },
              })
          },
        }
        if (payload.event in replies) replies[payload.event]()
      }
    )
  },
  beforeDestroy() {
    rendererEventsService.removeAllListeners(APP_TOOLS_EVENTS.replyChannel)
    rendererEventsService.removeAllListeners(LOGIN_EVENTS.replyChannel)
    rendererEventsService.removeAllListeners(SIGNUP_EVENTS.replyChannel)
  },
}
</script>

<style scoped>
.form-card {
  border-radius: 8px !important;
  position: relative;
}

.form-top-bar {
  height: 8px;
  width: 100%;
  position: absolute;
  top: 0;
  left: 0;
}

.position-relative {
  position: relative;
}

.centered-element {
  position: absolute;
  left: 50%;
  transform: translateX(-50%);
}
</style>
