import { required, maxLength, minValue } from 'vuelidate/lib/validators'

import { numericAccount } from '@/tools/customValidations'

const setConfig = (state, methods) => ({
  state,
  methods,
  fields: [
    {
      id: 'account',
      type: 'input',
      valueType: 'number',
      step: 1,
      label: 'shared.phone',
      errorMessage: 'starterLayout.editProfile.mobilePhoneRequired',
      color: 'primaryColor',
      icon: 'mdi-cellphone',
      autofocus: true,
      validators: {
        required,
        numericAccount,
        maxLength: maxLength(10),
        minValue: minValue(0),
      },
    },
  ],
  id: 'signup-phone-form',
  onSubmit: () => methods.submit(),
})

export default setConfig
